def count_fires(spec: str, blackouts: list[tuple[int, int]], a: int, b: int) -> int:
    # Parse spec
    fields = spec.split()
    if len(fields) != 3:
        raise ValueError("Wrong number of fields")

    minute_set = parse_field(fields[0], 59)
    hour_set = parse_field(fields[1], 23)
    weekday_set = parse_field(fields[2], 6)

    # Compute fires per week (minutes 0..10079)
    fires_per_week = 0
    for t in range(10080):
        if t % 60 in minute_set and t // 60 % 24 in hour_set and t // 1440 % 7 in weekday_set:
            fires_per_week += 1

    # Count alarm minutes in [start, end) using the repeating 10080-week pattern
    def count_alarm(start, end):
        if start >= end:
            return 0
        length = end - start
        w = length // 10080
        r = length % 10080
        p = start % 10080
        result = w * fires_per_week
        if p + r <= 10080:
            for t in range(p, p + r):
                if t % 60 in minute_set and t // 60 % 24 in hour_set and t // 1440 % 7 in weekday_set:
                    result += 1
        else:
            for t in range(p, 10080):
                if t % 60 in minute_set and t // 60 % 24 in hour_set and t // 1440 % 7 in weekday_set:
                    result += 1
            for t in range(0, p + r - 10080):
                if t % 60 in minute_set and t // 60 % 24 in hour_set and t // 1440 % 7 in weekday_set:
                    result += 1
        return result

    # Total alarm minutes in [a, b)
    total = count_alarm(a, b)

    # Subtract alarm minutes covered by blackouts
    for s, e in blackouts:
        start = max(a, s)
        end = min(b, e)
        if start < end:
            total -= count_alarm(start, end)

    return total


def parse_field(field, max_val):
    """Parse a field and return the set of valid values."""
    terms = field.split(',')
    if not terms or any(term.strip() == '' for term in terms):
        raise ValueError("Empty term")

    result = set()

    for term in terms:
        term = term.strip()
        # More than one '/' is invalid
        if term.count('/') > 1:
            raise ValueError("Multiple slashes")

        if '/' in term:
            parts = term.split('/')
            if len(parts) != 2:
                raise ValueError("Invalid step syntax")
            base, step_str = parts
            try:
                step = int(step_str)
            except ValueError:
                raise ValueError("Invalid step")
            if step < 1:
                raise ValueError("Step must be >= 1")

            if base == '*':
                for v in range(0, max_val + 1, step):
                    result.add(v)
            elif '-' in base:
                parts2 = base.split('-')
                if len(parts2) != 2:
                    raise ValueError("Invalid range")
                n, m = parts2
                try:
                    n = int(n)
                    m = int(m)
                except ValueError:
                    raise ValueError("Invalid range")
                if n > m:
                    raise ValueError("N > M")
                for v in range(n, m + 1, step):
                    result.add(v)
            else:
                try:
                    n = int(base)
                except ValueError:
                    raise ValueError("Invalid value")
                if n < 0 or n > max_val:
                    raise ValueError("Value out of range")
                for v in range(n, max_val + 1, step):
                    result.add(v)
        else:
            if term == '*':
                for v in range(0, max_val + 1):
                    result.add(v)
            elif '-' in term:
                parts = term.split('-')
                if len(parts) != 2:
                    raise ValueError("Invalid range")
                n, m = parts
                try:
                    n = int(n)
                    m = int(m)
                except ValueError:
                    raise ValueError("Invalid range")
                if n > m:
                    raise ValueError("N > M")
                if n < 0 or n > max_val or m < 0 or m > max_val:
                    raise ValueError("Value out of range")
                for v in range(n, m + 1):
                    result.add(v)
            else:
                try:
                    v = int(term)
                except ValueError:
                    raise ValueError("Invalid value")
                if v < 0 or v > max_val:
                    raise ValueError("Value out of range")
                result.add(v)

    return result
