def match_route(pattern: str, path: str) -> dict | None:
    """Match a URL-like path against a route pattern and return captured values."""
    if not pattern.startswith('/'):
        raise ValueError("pattern must start with '/'")
    if not path.startswith('/'):
        raise ValueError("path must start with '/'")

    pattern_segments = pattern[1:].split('/')
    path_segments = path[1:].split('/')

    named_names = {}
    parsed = []

    for seg in pattern_segments:
        if seg.startswith(':'):
            name = seg[1:]
            if '?' in name:
                name = name[:-1]
                typ = 'optional'
            else:
                typ = 'required'
            if not name or not all(c.isalnum() or c == '_' for c in name):
                raise ValueError(f"invalid name: {name}")
            if name in named_names:
                raise ValueError(f"duplicate name: {name}")
            named_names[name] = typ
            parsed.append(('named', name, typ))
        elif seg.startswith('#'):
            name = seg[1:]
            if not name or not all(c.isalnum() or c == '_' for c in name):
                raise ValueError(f"invalid name: {name}")
            if name in named_names:
                raise ValueError(f"duplicate name: {name}")
            named_names[name] = 'digit'
            parsed.append(('digit', name))
        elif seg.startswith('*'):
            name = seg[1:]
            if not name or not all(c.isalnum() or c == '_' for c in name):
                raise ValueError(f"invalid name: {name}")
            if name in named_names:
                raise ValueError(f"duplicate name: {name}")
            named_names[name] = 'wildcard'
            parsed.append(('wildcard', name))
        else:
            parsed.append(('literal', seg))

    memo = {}

    def match(pidx: int, pseg: tuple, pidx_next: int, path_idx: int) -> tuple:
        if pidx == len(parsed):
            if path_idx == len(path_segments):
                return (True, {})
            return (False, None)

        state = (pidx, path_idx)
        if state in memo:
            return memo[state]

        typ, val = pseg

        if typ == 'literal':
            if path_idx < len(path_segments) and path_segments[path_idx] == val:
                result = match(pidx_next, parsed[pidx_next], pidx_next + 1, path_idx + 1)
                if result[0]:
                    memo[state] = (True, result[1])
                    return (True, result[1])
                memo[state] = (False, None)
                return (False, None)
            memo[state] = (False, None)
            return (False, None)

        elif typ == 'named':
            if path_idx < len(path_segments) and path_segments[path_idx]:
                result = match(pidx_next, parsed[pidx_next], pidx_next + 1, path_idx + 1)
                if result[0]:
                    captured = result[1].copy()
                    captured[val] = path_segments[path_idx]
                    memo[state] = (True, captured)
                    return (True, captured)
                memo[state] = (False, None)
                return (False, None)
            memo[state] = (False, None)
            return (False, None)

        elif typ == 'optional':
            # Try 0 segments first, then 1 (greedy: minimum first)
            result = match(pidx_next, parsed[pidx_next], pidx_next + 1, path_idx)
            if result[0]:
                captured = result[1].copy()
                captured[val] = None
                memo[state] = (True, captured)
                return (True, captured)

            if path_idx < len(path_segments):
                result = match(pidx_next, parsed[pidx_next], pidx_next + 1, path_idx + 1)
                if result[0]:
                    captured = result[1].copy()
                    captured[val] = path_segments[path_idx]
                    memo[state] = (True, captured)
                    return (True, captured)
            memo[state] = (False, None)
            return (False, None)

        elif typ == 'digit':
            if path_idx < len(path_segments) and path_segments[path_idx].isdigit():
                result = match(pidx_next, parsed[pidx_next], pidx_next + 1, path_idx + 1)
                if result[0]:
                    captured = result[1].copy()
                    captured[val] = int(path_segments[path_idx])
                    memo[state] = (True, captured)
                    return (True, captured)
                memo[state] = (False, None)
                return (False, None)
            memo[state] = (False, None)
            return (False, None)

        elif typ == 'wildcard':
            # Try 0, 1, 2, ... segments (greedy: minimum first)
            for length in range(len(path_segments) - path_idx + 1):
                result = match(pidx_next, parsed[pidx_next], pidx_next + 1, path_idx + length)
                if result[0]:
                    captured = result[1].copy()
                    captured[val] = path_segments[path_idx:path_idx + length]
                    memo[state] = (True, captured)
                    return (True, captured)
            memo[state] = (False, None)
            return (False, None)

        raise ValueError("Unknown segment type")

    result = match(0, parsed[0], 1, 0)
    return result[1] if result[0] else None
